  text-align: center;
}

.hero .container {
  padding-top: var(--spacing-xl);
  padding-bottom: var(--spacing-xl);
}

.hero h1 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.hero-subtitle {
  font-size: 1.2rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-lg);
}

.btn-primary {
  background-color: #ffffff;
  color: var(--color-primary-dark);
  font-weight: 700;
}

.btn-primary:hover {
  background-color: var(--color-bg-alt);
}

.facilities {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg);
}

.facilities .container {
  padding-top: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
}

.facilities h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.memberships {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg-alt);
}

.memberships .container {
  padding-top: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
}

.memberships h2 {
  text-align: center;
  margin-bottom: var(--spacing-md);
}

.memberships-intro {
  text-align: center;
  font-size: 1.05rem;
  margin-bottom: var(--spacing-xl);
  color: var(--color-text-light);
}

.table-wrapper {
  overflow-x: auto;
  margin-bottom: var(--spacing-lg);
  border-radius: 8px;
}

.memberships-note {
  text-align: center;
  font-size: 0.9rem;
  color: var(--color-text-light);
  margin-top: var(--spacing-md);
}

.memberships-cta {
  text-align: center;
  margin-top: var(--spacing-xl);
}

.testimonials {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg);
}

.testimonials .container {
  padding-top: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
}

.testimonials h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.testimonial-card {
  background-color: var(--color-primary-light);
  border: 1px solid #ffcdd2;
  border-radius: 8px;
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.testimonial-text {
  font-style: italic;
  color: var(--color-text);
  margin-bottom: var(--spacing-md);
  font-size: 1.05rem;
  line-height: 1.7;
}

.testimonial-author {
  font-weight: 600;
  color: var(--color-primary-dark);
  font-size: 0.95rem;
  margin: 0;
}

.contact-section {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg-alt);
}

.contact-section .container {
  padding-top: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
}

.contact-section h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.contact-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-2xl);
  align-items: start;
}

.contact-info {
  background-color: var(--color-bg);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border: 1px solid var(--color-border);
}

.contact-info h3 {
  color: var(--color-primary-dark);
  margin-top: var(--spacing-md);
}

.contact-info h3:first-child {
  margin-top: 0;
}

.contact-info p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}

.hours-list {
  list-style: none;
  padding: 0;
  color: var(--color-text);
}

.hours-list li {
  padding: var(--spacing-xs) 0;
  color: var(--color-text);
}

.contact-form-wrapper {
  background-color: var(--color-bg);
  padding: var(--spacing-lg);
  border-radius: 8px;
  border: 1px solid var(--color-border);
}

.contact-form-wrapper h3 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-lg);
}

.form-group {
  margin-bottom: var(--spacing-lg);
}

.contact-form button {
  width: 100%;
}

@media (max-width: 600px) {
  .hero {
    padding: var(--spacing-xl) 0;
  }

  .hero .container {
    padding-top: var(--spacing-lg);
    padding-bottom: var(--spacing-lg);
  }

  .hero-subtitle {
    font-size: 1rem;
  }

  .memberships, .facilities, .testimonials, .contact-section {
    padding: var(--spacing-xl) 0;
  }

  .contact-content {
    grid-template-columns: 1fr;
    gap: var(--spacing-lg);
  }

  .table-wrapper {
    border-radius: 4px;
  }

  table {
    font-size: 0.85rem;
  }

  th, td {
    padding: var(--spacing-sm) var(--spacing-xs);
  }
}

@media (min-width: 601px) {
  .contact-content {
    grid-template-columns: 1fr 1fr;
  }
}
